head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > setInstanceNode]<br/>XML Document 또는 XML Element 를 Instance 의 XPath 에 해당하는 경로에 위치시킵니다.",
    "validation" : [
        "doc(필수) 파라미터로 추가할 XML Document 또는 XML Element 를 설정할 수 있어야 합니다.",
        "xpath(필수) 파라미터로 노드를 추가할 경로의 XPath 를 설정할 수 있어야 합니다.",
        "mode='replace' (기본값) : xpath 노드의 모든 자식 노드를 제거한 후 doc 노드를 자식으로 추가해야 합니다.",
        "mode='append' : xpath 노드의 자식 노드를 유지하고 doc 노드를 자식으로 추가해야 합니다.",
        "mode='insertBeforeSibling' : xpath 노드의 앞에 형제 노드로 doc 노드를 삽입해야 합니다.",
        "mode='appendSibling' : xpath 노드의 부모에 자식으로 doc 노드를 추가해야 합니다.",
        "xpath 파라미터에 해당하는 노드가 존재하지 않으면 생성한 후 처리해야 합니다.",
        "ref 속성으로 데이터가 바인딩 된 상태이면 바인딩된 UI 컴포넌트가 자동 갱신되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 시나리오 실행 전 instance 원본 보존용 스냅샷
    scwin._origBookstore = WebSquare.xml.serialize(WebSquare.ModelUtil.findInstanceNode("bookstore"));
    scwin._origSelectedBook = WebSquare.xml.serialize(WebSquare.ModelUtil.findInstanceNode("selectedBook"));
};



// 특정 instance 노드를 원본 직렬화 문자열로 복원 (자식만 교체하여 wrap 중첩 방지)
scwin._resetNodeFromOrigin = function (xpath, origSerialized) {
    var instNode = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!instNode) return;
    while (instNode.firstChild) instNode.removeChild(instNode.firstChild);
    var origNode = WebSquare.xml.parse(origSerialized).documentElement;
    for (var i = 0; i < origNode.childNodes.length; i++) {
        if (origNode.childNodes[i].nodeType === 1) {
            instNode.appendChild(origNode.childNodes[i].cloneNode(true));
        }
    }
};

// 매 시나리오 실행 전 instance 데이터 원본으로 복구 (이전 시나리오 결과 누적 방지)
scwin.resetInstance = function () {
    scwin._resetNodeFromOrigin("bookstore", scwin._origBookstore);
    scwin._resetNodeFromOrigin("selectedBook", scwin._origSelectedBook);

    // 시나리오 5 에서 동적 생성된 newRoot 정리
    var newRoot = WebSquare.ModelUtil.findInstanceNode("newRoot");
    if (newRoot && newRoot.parentNode) {
        newRoot.parentNode.removeChild(newRoot);
    }

    // ref 바인딩 input 강제 갱신 (DOM 직접 조작은 detectChange 미발생)
    ibx_selectedTitle.setValue(WebSquare.ModelUtil.findInstanceNode("selectedBook/title").textContent);
};



// 특정 xpath 노드를 serialize 하여 한 줄 문자열로 반환 (출력용)
scwin.dumpXPath = function (xpath) {
    var node = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!node) return "(node not found)";
    var s = WebSquare.xml.serialize(node);
    return s.replace(/\s+/g, " ").replace(/>\s+</g, "><");
};



scwin.btn_setInstanceNode_onclick = function () {
    var scenario = par_scenario.getValue();
    scwin.resetInstance();

    if (scenario === "1") {
        // 시나리오 1 : mode='replace' - selectedBook 자식 제거 후 bookstore/book 추가
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : mode='replace' - selectedBook 자식 제거 후 bookstore/book 추가 ──");

        var doc = WebSquare.ModelUtil.findInstanceNode("bookstore/book");
        WebSquare.ModelUtil.setInstanceNode(doc, "selectedBook", null, "replace");

        wf_body_bottom.getObj("scwin").setReturnValue("결과 selectedBook : " + scwin.dumpXPath("selectedBook"));
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] selectedBook 자식이 book 으로 교체 : " + (scwin.dumpXPath("selectedBook").indexOf("<book") > -1 && scwin.dumpXPath("selectedBook").indexOf("<author") === -1));
    } else if (scenario === "2") {
        // 시나리오 2 : mode='append' - selectedBook 자식 유지 + bookstore/book 자식으로 추가
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : mode='append' - selectedBook 자식 유지 + bookstore/book 자식으로 추가 ──");

        var doc = WebSquare.ModelUtil.findInstanceNode("bookstore/book");
        WebSquare.ModelUtil.setInstanceNode(doc, "selectedBook", null, "append");

        wf_body_bottom.getObj("scwin").setReturnValue("결과 selectedBook : " + scwin.dumpXPath("selectedBook"));
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] 기존 자식(author) 유지 + book 추가 : " + (scwin.dumpXPath("selectedBook").indexOf("<author") > -1 && scwin.dumpXPath("selectedBook").indexOf("<book") > -1));
    } else if (scenario === "3") {
        // 시나리오 3 : mode='insertBeforeSibling' - bookstore/book[2] 앞에 selectedBook 자식 노드(title) 형제 삽입
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : mode='insertBeforeSibling' - bookstore/book[2] 앞에 형제 노드 삽입 ──");

        var doc = WebSquare.ModelUtil.findInstanceNode("selectedBook/title");
        WebSquare.ModelUtil.setInstanceNode(doc, "bookstore/book[2]", null, "insertBeforeSibling");

        wf_body_bottom.getObj("scwin").setReturnValue("결과 bookstore : " + scwin.dumpXPath("bookstore"));
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] bookstore 자식 수 : " + WebSquare.ModelUtil.findInstanceNode("bookstore").childNodes.length + " (기존 2 → 3 이어야 PASS)");
    } else if (scenario === "4") {
        // 시나리오 4 : mode='appendSibling' - bookstore/book 의 부모(bookstore) 에 selectedBook 자식 추가
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : mode='appendSibling' - bookstore/book 의 부모(bookstore) 에 자식 추가 ──");

        var doc = WebSquare.ModelUtil.findInstanceNode("selectedBook/author");
        WebSquare.ModelUtil.setInstanceNode(doc, "bookstore/book[1]", null, "appendSibling");

        wf_body_bottom.getObj("scwin").setReturnValue("결과 bookstore : " + scwin.dumpXPath("bookstore"));
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] bookstore 자식 수 : " + WebSquare.ModelUtil.findInstanceNode("bookstore").childNodes.length + " (기존 2 → 3 이어야 PASS, author 형제로 추가됨)");
    } else if (scenario === "5") {
        // 시나리오 5 : xpath 미존재 시 노드 자동 생성
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 5 : xpath 미존재 시 자동 생성 ──");

        var doc = WebSquare.ModelUtil.findInstanceNode("bookstore/book[1]");
        WebSquare.ModelUtil.setInstanceNode(doc, "newRoot/newParent/newChild", null, "replace");

        var created = WebSquare.ModelUtil.findInstanceNode("newRoot/newParent/newChild");
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] 미존재 xpath 자동 생성 여부 : " + (created !== null));
        wf_body_bottom.getObj("scwin").setReturnValue("생성된 newChild : " + scwin.dumpXPath("newRoot/newParent/newChild"));

        // 정리
        WebSquare.ModelUtil.removeInstanceNode("newRoot");
    } else if (scenario === "6") {
        // 시나리오 6 : ref 바인딩 컴포넌트 자동 갱신
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 6 : ref 바인딩 input 자동 갱신 (selectedBook/title) ──");

        // 갱신 전 ref 바인딩 값
        wf_body_bottom.getObj("scwin").setReturnValue("갱신 전 ibx_selectedTitle 값 : " + ibx_selectedTitle.getValue());

        // bookstore/book[1]/title (Harry Potter) 를 selectedBook 에 replace 로 설정
        // → selectedBook/title 도 교체되며 ref 바인딩 input 자동 갱신되어야 함
        var doc = WebSquare.ModelUtil.findInstanceNode("bookstore/book[1]/title");
        WebSquare.ModelUtil.setInstanceNode(doc, "selectedBook", null, "replace");

        wf_body_bottom.getObj("scwin").setReturnValue("갱신 후 ibx_selectedTitle 값 : " + ibx_selectedTitle.getValue());
        wf_body_bottom.getObj("scwin").setReturnValue("[검증] ref 바인딩 자동 갱신 : " + (ibx_selectedTitle.getValue() === "Harry Potter"));
    }
};
